import {W,H} from './config.js';import {createInput} from './input.js';import {createWorld,updateWorld,clickWorld,interact,addOrder} from './world.js';import {render} from './render.js';import {sound,music} from './audio.js';
const canvas=document.querySelector('#game'),ctx=canvas.getContext('2d');canvas.width=W;canvas.height=H;const input=createInput(canvas);const shot=new URLSearchParams(location.search).get('shot');let world=createWorld(shot);let last=performance.now();
function resize(){const d=devicePixelRatio||1;canvas.width=W*d;canvas.height=H*d;ctx.setTransform(d,0,0,d,0,0)}window.addEventListener('resize',resize);resize();
function reset(){world=createWorld('');music(false)}
function loop(now){const dt=Math.min(.05,(now-last)/1000);last=now;for(const e of input.take()){if(e.type==='pointer'){clickWorld(world,e.x,e.y);sound('plate')}else if(e.key===' '||e.key==='e'){interact(world);sound(world.message?.includes('Served')?'serve':world.message?.includes('Wrong')?'error':'chop')}else if(e.key==='p'){world.paused=!world.paused;music(!world.paused&&world.screen==='playing')}else if(e.key==='r'){reset()}else if(e.key==='arrowleft'||e.key==='a')world.vx=-1;else if(e.key==='arrowright'||e.key==='d')world.vx=1;else if(e.key==='arrowup'||e.key==='w')world.chef.y=Math.max(390,world.chef.y-22);else if(e.key==='arrowdown'||e.key==='s')world.chef.y=Math.min(575,world.chef.y+22)}if(input.keys.has('arrowleft')||input.keys.has('a'))world.vx=-190;else if(input.keys.has('arrowright')||input.keys.has('d'))world.vx=190;else world.vx=0;if(world.screen==='playing'&&!world.paused)music(true);updateWorld(world,dt);render(ctx,world);requestAnimationFrame(loop)}requestAnimationFrame(loop);
