export function createInput(canvas){const keys=new Set(),events=[];window.addEventListener('keydown',e=>{const k=e.key.toLowerCase();if(['arrowup','arrowdown','arrowleft','arrowright',' '].includes(k))e.preventDefault();if(!keys.has(k))events.push({type:'key',key:k});keys.add(k)});window.addEventListener('keyup',e=>keys.delete(e.key.toLowerCase()));canvas.addEventListener('pointerdown',e=>{const r=canvas.getBoundingClientRect();events.push({type:'pointer',x:(e.clientX-r.left)*canvas.width/r.width,y:(e.clientY-r.top)*canvas.height/r.height})});return{keys,events,take(){return events.splice(0)}}}
