import {RECIPES,INGREDIENTS,STATIONS,SHIFT} from './config.js';
export function createWorld(shot=''){const w={time:SHIFT,coins:0,served:0,combo:0,bestCombo:0,orders:[],chef:{x:414,y:523,held:null},board:null,pans:[null,null],assembly:[],plated:null,spawn:0,paused:false,flash:0,message:'',screen:shot==='play'||shot==='rush'?'playing':'title',elapsed:0};if(shot==='play'||shot==='rush'){w.time=shot==='play'?94:24;w.coins=46;w.combo=2;w.bestCombo=4;w.orders=[makeOrder(0,shot==='rush'?9:28),makeOrder(2,shot==='rush'?16:44),makeOrder(4,shot==='rush'?22:52)];if(shot==='rush')w.orders.push(makeOrder(1,19));w.board={item:'tomato',chop:2};w.assembly=['pasta','tomato'];w.plated={items:['bun','patty','cheese'],recipe:3};w.pans[0]={item:'patty',cook:.72,burn:0};w.chef.x=780}return w}
function makeOrder(index,seconds=55){return{recipe:index,remaining:seconds,limit:seconds,id:Math.random()}}
export function addOrder(w,index,seconds){w.orders.push(makeOrder(index,seconds))}
function nearby(w,station){const p=STATIONS[station];return Math.hypot(w.chef.x-p.x,w.chef.y-p.y)<100}
function nearestStation(x,y){return Object.entries(STATIONS).sort((a,b)=>Math.hypot(x-a[1].x,y-a[1].y)-Math.hypot(x-b[1].x,y-b[1].y))[0][0]}
export function clickWorld(w,x,y){if(w.screen==='title'){w.screen='playing';return}if(w.screen==='results'){w.screen='title';return}if(y<175){const i=Math.floor((x-190)/265);if(i>=0&&i<w.orders.length)w.message=`${RECIPES[w.orders[i].recipe].name} ticket`;return}w.target=nearestStation(x,y);w.targetUntil=5;if(y<356){const ix=Math.floor((x-64)/112);const items=['tomato','lettuce','patty','bun','pasta','cheese','cucumber'];if(ix>=0&&ix<items.length){w.chef.held=items[ix];w.message=`Picked up ${INGREDIENTS[items[ix]].name}`}}}
function recipeFor(items){return RECIPES.findIndex(r=>r.items.length===items.length&&r.items.slice().sort().join('|')===items.slice().sort().join('|'))}
export function interact(w){
 if(w.screen!=='playing')return;
 if(w.chef.held){const item=w.chef.held;
  if(item.endsWith('_chopped')&&nearby(w,'assembly')){w.assembly.push(item.replace('_chopped',''));w.chef.held=null;w.message='Freshly chopped';return}
  if(INGREDIENTS[item]?.chop){if(nearby(w,'board')){if(!w.board||w.board.item!==item)w.board={item,chop:0};w.board.chop++;if(w.board.chop>=3){w.chef.held=item+'_chopped';w.board=null}w.message='Chop!';return}w.message='Take it to the board';return}
  if(INGREDIENTS[item]?.cook){if(nearby(w,'stove')){const empty=w.pans.findIndex(p=>!p);if(empty>=0){w.pans[empty]={item,cook:0,burn:0};w.chef.held=null;w.message='On the heat';return}}w.message='Take it to a pan';return}
  if(nearby(w,'assembly')){w.assembly.push(item);w.chef.held=null;w.message='Added to plate';return}
  w.message='Carry it to assembly';return;
 }
 if(nearby(w,'board')&&w.board){w.chef.held=w.board.item+'_chopped';w.board=null;w.message='Ready to plate'}
 else if(nearby(w,'stove')){const i=w.pans.findIndex(p=>p&&p.cook>=1);if(i>=0){w.chef.held=w.pans[i].item;w.pans[i]=null;w.message='Perfectly cooked'}else w.message='Cooking...'}
 else if(nearby(w,'assembly')&&w.assembly.length){const recipe=recipeFor(w.assembly);w.plated={items:w.assembly.slice(),recipe};w.assembly=[];w.message=recipe>=0?RECIPES[recipe].name+' plated':'Try another combination'}
 else if(nearby(w,'window')){if(!w.plated){w.message='Plate a dish first';return}const i=w.orders.findIndex(o=>o.recipe===w.plated.recipe);if(i<0){w.combo=0;w.coins=Math.max(0,w.coins-4);w.message='Wrong dish! Combo lost'}else{const o=w.orders.splice(i,1)[0],tip=Math.ceil(o.remaining/8);w.coins+=10+tip+Math.min(12,w.combo*2);w.served++;w.combo++;w.bestCombo=Math.max(w.bestCombo,w.combo);w.message=`Served! +${10+tip+Math.min(12,(w.combo-1)*2)} coins`}w.plated=null}
}
export function updateWorld(w,dt){if(w.screen!=='playing'||w.paused)return;w.elapsed+=dt;w.time-=dt;w.flash=Math.max(0,w.flash-dt);w.spawn+=dt;w.chef.x=Math.max(55,Math.min(1225,w.chef.x+(w.vx||0)*dt));if(w.targetUntil>0){const t=STATIONS[w.target];if(t){const d=t.x-w.chef.x;w.chef.x+=Math.sign(d)*Math.min(Math.abs(d),170*dt);w.targetUntil-=dt}}if(w.time<=0){w.time=0;w.screen='results';return}for(const p of w.pans)if(p){p.cook=Math.min(1.2,p.cook+dt/5);if(p.cook>=1)p.burn+=dt;if(p.burn>7){w.pans[w.pans.indexOf(p)]=null;w.time=Math.max(0,w.time-7);w.combo=0;w.message='Burnt! Lost 7 sec';w.flash=.7}}for(const o of w.orders)o.remaining-=dt;const expired=w.orders.filter(o=>o.remaining<=0).length;if(expired){w.orders=w.orders.filter(o=>o.remaining>0);w.combo=0;w.coins=Math.max(0,w.coins-expired*3);w.message='Ticket expired - combo lost';w.flash=.8}if(w.spawn>12&&w.orders.length<Math.min(4,2+Math.floor(w.elapsed/35))){w.spawn=0;const idx=Math.floor(Math.random()*RECIPES.length);w.orders.push(makeOrder(idx,Math.max(28,59-w.elapsed*.12)));w.message='New ticket!'} }
