function drawBoard(c,w){rr(c,0,0,W,174,0,'#263b42');txt(c,'SIZZLE STATION',25,35,22,C.gold,'left','900');txt(c,'SHIFT',1050,28,12,'#b7cbc5');txt(c,`${Math.ceil(w.time)}s`,1050,61,31,w.time<10?C.red:C.cream,'left','900');txt(c,`COINS  ${w.coins}`,1150,28,12,'#b7cbc5');txt(c,`${w.coins}`,1150,61,28,C.gold,'left','900');txt(c,`COMBO  x${w.combo}`,25,70,15,w.combo>1?C.mint:'#c3d4ca','left','800');for(let i=0;i<4;i++){const o=w.orders[i];const x=190+i*265;rr(c,x,12,245,142,12,o?'#f5e7c8':'#32484e',o&&o.remaining<10?C.red:'#516b6d');if(!o){txt(c,'OPEN TICKET',x+122,76,15,'#789096','center');continue}const r=RECIPES[o.recipe];txt(c,r.name,x+14,39,17,C.ink,'left','800');txt(c,`${Math.ceil(o.remaining)}s`,x+220,39,18,o.remaining<10?C.red:'#8b6147','right','900');r.items.forEach((it,j)=>food(c,it,x+34+j*48,91,.42));c.fillStyle=o.remaining<10?C.red:C.mint;c.fillRect(x+14,126,217*Math.max(0,o.remaining/o.limit),5)}}
