let ctx=null,master=null,beat=null;
function audio(){if(!ctx){ctx=new AudioContext();master=ctx.createGain();master.gain.value=.12;master.connect(ctx.destination)}if(ctx.state==='suspended')ctx.resume();return ctx}
function tone(freq,duration,type='sine',volume=.2,delay=0){const c=audio(),o=c.createOscillator(),g=c.createGain();o.type=type;o.frequency.setValueAtTime(freq,c.currentTime+delay);g.gain.setValueAtTime(.001,c.currentTime+delay);g.gain.exponentialRampToValueAtTime(volume,c.currentTime+delay+.015);g.gain.exponentialRampToValueAtTime(.001,c.currentTime+delay+duration);o.connect(g);g.connect(master);o.start(c.currentTime+delay);o.stop(c.currentTime+delay+duration+.03)}
export function sound(kind){if(kind==='chop'){tone(190,.07,'triangle',.24);tone(95,.045,'square',.12,.025)}else if(kind==='sizzle'){tone(130,.25,'sawtooth',.08)}else if(kind==='ding'){tone(880,.22,'sine',.22);tone(1320,.3,'sine',.14,.08)}else if(kind==='serve'){tone(660,.16,'triangle',.2);tone(990,.25,'triangle',.19,.11)}else if(kind==='error'){tone(160,.26,'square',.16);tone(110,.3,'square',.12,.14)}else if(kind==='plate'){tone(520,.09,'sine',.14);tone(730,.12,'sine',.1,.06)}}
export function music(on){if(on&&beat===null){beat=setInterval(()=>{tone(164,.12,'triangle',.024);tone(247,.12,'triangle',.018,.2)},820)}else if(!on&&beat!==null){clearInterval(beat);beat=null}}
